SELECT CASE WHEN budget >= 3399000 THEN 'high' WHEN budget >= 966000 THEN 'mid' ELSE 'low' END AS budget_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) AS dept_name_values, SUM(budget) AS total_budget, ROUND((100 * SUM(CASE WHEN dept_name = 'Sales' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_sales FROM departments WHERE location <> 'Berlin' AND location IS NULL GROUP BY 1 HAVING ROUND((100 * SUM(CASE WHEN dept_name = 'Sales' THEN 1 ELSE 0 END)) / COUNT(*), 1) > 58 ORDER BY pct_sales, budget_bucket LIMIT 10;
